{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "For buildings constructed or remodeled after July 1, 2023, but before July 1, 2025, the bill would require clear entry-resistant film on the glass panels of each exterior entry or basement-level window and door.",
      "rationale": "Conveys the construction/remodeling dates, required film, and covered glass surfaces. The preceding context establishes that these are public school buildings, including charter schools; the entry-resistant requirement conveys the protective purpose."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would change the glass-security requirements for public school buildings, including public charter school buildings, that are constructed or remodeled on or after July 1, 2025. They would need clear window film or security glazing that meets a nationally recognized forced-entry test standard, such as ASTM F3561, at each exterior entry or door and its adjoining glazing, and at secure interior vestibules serving as primary entrances.",
      "rationale": "Conveys the covered schools, construction/remodeling trigger, date, alternative materials, test standard, and required installation locations."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The state-level safety team would have to develop and update compliance guidelines",
      "rationale": "Identifies the responsible team and its duties to develop and update compliance guidelines. The statutory cross-reference is not essential to identify the duty."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The state-level safety team would have to develop and update compliance guidelines and send them to the state fire marshal for incorporation into rules.",
      "rationale": "Conveys the team's mandatory transmission of the guidelines to the fire marshal and their incorporation into rules."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "The fire marshal would be allowed to make rules to carry out the bill.",
      "rationale": "Conveys rulemaking authorization but omits the requirement that rules be promulgated in accordance with the Uniform Administrative Procedures Act."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law for guidelines and rulemaking, and on July 1, 2025, for all other purposes.",
      "rationale": "Conveys both effective dates and the purposes governed by each."
    }
  ]
}
